SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, ROW_NUMBER() OVER (PARTITION BY brand, supplier_id ORDER BY launch_date, id) event_seq, LAG(price, 1) OVER w_hist prev_price, SUM(stock_qty) OVER (PARTITION BY brand ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_stock_qty, MAX(stock_qty) OVER (PARTITION BY supplier_id, category) supplier_id_max_stock_qty, FIRST_VALUE(price, TRUE) OVER (ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_price FROM products WINDOW w_hist AS (ORDER BY price, id);
